// =============================================================================
// File:        fft_256.sv
// Project:     Project Auris — FPGA-Accelerated Assistive Audio
// Module:      fft_256
// Description: AXI-Stream wrapper around the Xilinx xfft IP core configured
//              for a 256-point, pipelined, streaming-I/O, 16-bit fixed-
//              point FFT with Block Floating Point scaling.
//
//              The IP is generated by fpga/scripts/create_ip.tcl with
//              module name `fft_256_core`.  This file is a thin wrapper
//              that exposes the full AXI-Stream interface (data, config,
//              status, event) to the rest of the design.
//
//              s_axis_data_tdata[31:0]  layout:  {imag[15:0], real[15:0]}
//              m_axis_data_tdata[31:0]  layout:  {imag[15:0], real[15:0]}
//
// Author:      [generated]
// Created:     2026-07
// Clock Domain: CD_DSP (96 MHz)
// =============================================================================
`default_nettype none
`timescale 1ns / 1ps

module fft_256 import auris_pkg::*; (
    // ---- Clock and reset ---------------------------------------------------
    input  wire        aclk,
    input  wire        aresetn,

    // ---- Slave AXI-Stream data input ---------------------------------------
    input  wire [31:0] s_axis_data_tdata,
    input  wire        s_axis_data_tvalid,
    output wire        s_axis_data_tready,
    input  wire        s_axis_data_tlast,

    // ---- Slave AXI-Stream config input -------------------------------------
    input  wire [7:0]  s_axis_config_tdata,
    input  wire        s_axis_config_tvalid,
    output wire        s_axis_config_tready,

    // ---- Master AXI-Stream data output -------------------------------------
    output wire [31:0] m_axis_data_tdata,
    output wire [7:0]  m_axis_data_tuser,
    output wire        m_axis_data_tvalid,
    output wire        m_axis_data_tlast,

    // ---- Master AXI-Stream status output -----------------------------------
    output wire [7:0]  m_axis_status_tdata,
    output wire        m_axis_status_tvalid,

    // ---- Event outputs -----------------------------------------------------
    output wire        event_frame_started,
    output wire        event_tlast_unexpected,
    output wire        event_data_in_channel_halt
);

    // -------------------------------------------------------------------------
    // Xilinx xfft IP instantiation
    // -------------------------------------------------------------------------
    // Module name must match the IP definition in create_ip.tcl.
    // Configuration: transform_length=256, data_width=16, phase_factor_width=16,
    //               architecture=pipelined_streaming, scaling=block_floating_point,
    //               rounding=convergent.
    fft_256_core u_fft_256_core (
        .aclk                      (aclk),
        .aresetn                   (aresetn),
        .s_axis_data_tdata         (s_axis_data_tdata),
        .s_axis_data_tvalid        (s_axis_data_tvalid),
        .s_axis_data_tready        (s_axis_data_tready),
        .s_axis_data_tlast         (s_axis_data_tlast),
        .s_axis_config_tdata       (s_axis_config_tdata),
        .s_axis_config_tvalid      (s_axis_config_tvalid),
        .s_axis_config_tready      (s_axis_config_tready),
        .m_axis_data_tdata         (m_axis_data_tdata),
        .m_axis_data_tuser         (m_axis_data_tuser),
        .m_axis_data_tvalid        (m_axis_data_tvalid),
        .m_axis_data_tlast         (m_axis_data_tlast),
        .m_axis_status_tdata       (m_axis_status_tdata),
        .m_axis_status_tvalid      (m_axis_status_tvalid),
        .event_frame_started       (event_frame_started),
        .event_tlast_unexpected    (event_tlast_unexpected),
        .event_tlast_missing       (),
        .event_data_in_channel_halt(event_data_in_channel_halt)
    );

endmodule : fft_256

`default_nettype wire
